# %% [markdown]
# ## Step 3 — Define the Ticket Schema
#
# We want each ticket to have: `category` (one of: billing, technical, account, feedback), `priority` (high/medium/low), `summary` (short description), and `requires_immediate_response` (boolean).
#
# This is the contract the LLM must follow.

# %%
ticket_schema = {
    "type": "object",
    "properties": {
        "category": {
            "type": "string",
            "enum": ["billing", "technical", "account", "feedback"]
        },
        "priority": {
            "type": "string",
            "enum": ["high", "medium", "low"]
        },
        "summary": {"type": "string"},
        "requires_immediate_response": {"type": "boolean"}
    },
    "required": ["category", "priority", "summary", "requires_immediate_response"]
}

print("TriageTicket Schema:")
print(json.dumps(ticket_schema, indent=2))

# %% [markdown]
# ## Step 4 — Validate Against Schema
#
# Build a validator that checks if parsed JSON matches the schema. This is what runs on the output side.

# %%
def validate_schema(data, schema):
    """Check if data matches schema. Returns list of errors (empty = valid)."""
    errors = []
    
    if schema.get("type") == "object":
        if not isinstance(data, dict):
            return [f"Expected object, got {type(data).__name__}"]
        
        # Check required fields
        for field in schema.get("required", []):
            if field not in data:
                errors.append(f"Required field missing: {field}")
        
        # Validate each field
        for key, value in data.items():
            if key in schema.get("properties", {}):
                prop_schema = schema["properties"][key]
                prop_errors = _validate_value(value, prop_schema, key)
                errors.extend(prop_errors)
    
    return errors

def _validate_value(value, schema, path=""):
    """Recursively validate a single value against a schema."""
    errors = []
    schema_type = schema.get("type")
    
    if schema_type == "string":
        if not isinstance(value, str):
            errors.append(f"{path}: expected string, got {type(value).__name__}")
        elif "enum" in schema and value not in schema["enum"]:
            errors.append(f"{path}: '{value}' not in {schema['enum']}")
    
    elif schema_type == "boolean":
        if not isinstance(value, bool):
            errors.append(f"{path}: expected boolean, got {type(value).__name__}")
    
    return errors

# Test the validator
test_ticket = {"category": "technical", "priority": "high", "summary": "Login broken", "requires_immediate_response": True}
errors = validate_schema(test_ticket, ticket_schema)
print(f"Valid ticket: {errors}")

invalid_ticket = {"category": "INVALID", "priority": "high", "summary": "Test"}
errors = validate_schema(invalid_ticket, ticket_schema)
print(f"Invalid ticket errors: {errors}")

# %% [markdown]
# ## Step 5 — Extract & Validate a Real Email
#
# Now send a real support email to the LLM and ask it to produce a TriageTicket as JSON. Use strict mode to ensure the output matches the schema.

# %%
email_to_triage = raw_emails[0]

system_prompt = """You are a support ticket triage expert. Extract ticket information from a customer email.
Respond ONLY with valid JSON matching this schema:
{
  "category": one of [billing, technical, account, feedback],
  "priority": one of [high, medium, low],
  "summary": a 1-2 sentence summary of the issue,
  "requires_immediate_response": true if the customer is angry or blocked, false otherwise
}
No preamble. No markdown. Only JSON."""

user_message = f"Triage this support email:\n\n{email_to_triage}"

resp = await lrn_llm.call(
    [{"role": "user", "content": user_message}],
    system=system_prompt,
    max_tokens=200
)

raw_response = lrn_llm.text(resp)
print("LLM Response:")
print(raw_response)
print()

# Parse and validate
try:
    ticket = json.loads(raw_response)
    errors = validate_schema(ticket, ticket_schema)
    if errors:
        print(f"Validation errors: {errors}")
    else:
        print("✅ Ticket is valid!")
        print(json.dumps(ticket, indent=2))
except json.JSONDecodeError as e:
    print(f"❌ Failed to parse JSON: {e}")

