# %% [markdown]
# ## Step 7 — Full Extraction Pipeline with Retries
#
# Combine validation with retry logic: if the first attempt fails, send errors back to the model and ask it to fix the output.

# %%
async def extract_ticket_with_retry(email, max_retries=2):
    """Extract a ticket from an email with automatic retry on validation failure."""
    system_prompt = """You are a support ticket triage expert. Extract ticket information from a customer email.
Respond ONLY with valid JSON matching this schema:
{
  "category": one of [billing, technical, account, feedback],
  "priority": one of [high, medium, low],
  "summary": a 1-2 sentence summary of the issue,
  "requires_immediate_response": true if the customer is angry or blocked, false otherwise
}
No preamble. No markdown. Only JSON."""
    
    messages = [{"role": "user", "content": f"Triage this support email:\n\n{email}"}]
    
    for attempt in range(max_retries):
        resp = await lrn_llm.call(messages, system=system_prompt, max_tokens=200)
        raw_response = lrn_llm.text(resp)
        
        try:
            ticket = json.loads(raw_response)
        except json.JSONDecodeError as e:
            print(f"Attempt {attempt + 1}: JSON parse error -- {e}")
            continue
        
        errors = validate_schema(ticket, ticket_schema)
        if not errors:
            return ticket
        
        print(f"Attempt {attempt + 1}: Schema validation failed -- {errors}")
        if attempt < max_retries - 1:
            messages.append({"role": "assistant", "content": raw_response})
            messages.append({
                "role": "user",
                "content": f"Fix these validation errors: {errors}. Return valid JSON only."
            })
    
    return None

# Test with the billing email
ticket = await extract_ticket_with_retry(raw_emails[1])
if ticket:
    print("✅ Extracted ticket:")
    print(json.dumps(ticket, indent=2))
else:
    print("❌ Failed to extract ticket after retries")

